CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY,email TEXT UNIQUE NOT NULL,full_name TEXT NOT NULL,phone TEXT,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS career_profiles (user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,resume_name TEXT,roles TEXT,skills TEXT,locations TEXT,experience TEXT,service TEXT,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
ALTER TABLE career_profiles ADD COLUMN IF NOT EXISTS salary_expectation TEXT;
CREATE TABLE IF NOT EXISTS onboarding_progress (user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,current_step TEXT NOT NULL DEFAULT 'user',completed_steps TEXT[] NOT NULL DEFAULT '{}',is_complete BOOLEAN NOT NULL DEFAULT FALSE,updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS payments (id BIGSERIAL PRIMARY KEY,user_id UUID REFERENCES users(id) ON DELETE CASCADE,payment_id TEXT UNIQUE NOT NULL,amount INTEGER NOT NULL,mode TEXT NOT NULL,status TEXT NOT NULL,verified_at TIMESTAMPTZ,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS career_workflows (user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,schedule TEXT NOT NULL,timezone TEXT NOT NULL DEFAULT 'Asia/Kolkata',sources TEXT[] NOT NULL,minimum_score INTEGER NOT NULL,daily_limit INTEGER NOT NULL,status TEXT NOT NULL,last_run_at TIMESTAMPTZ,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS application_preferences (user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,review_required BOOLEAN NOT NULL,retries INTEGER NOT NULL,updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS notification_preferences (user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,email_notifications BOOLEAN NOT NULL,daily_summary BOOLEAN NOT NULL,updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS setup_step_events (id BIGSERIAL PRIMARY KEY,user_id UUID REFERENCES users(id) ON DELETE CASCADE,step TEXT NOT NULL,payload JSONB NOT NULL,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS email_logs (id BIGSERIAL PRIMARY KEY,user_id UUID REFERENCES users(id) ON DELETE CASCADE,recipient TEXT NOT NULL,step TEXT NOT NULL,status TEXT NOT NULL,provider_id TEXT,created_at TIMESTAMPTZ DEFAULT NOW());
ALTER TABLE email_logs ADD COLUMN IF NOT EXISTS error_code TEXT;
CREATE TABLE IF NOT EXISTS discovered_jobs (id BIGSERIAL PRIMARY KEY,source TEXT NOT NULL,external_id TEXT NOT NULL,title TEXT NOT NULL,company TEXT NOT NULL,location TEXT,source_url TEXT NOT NULL,published_at TIMESTAMPTZ,raw_data JSONB,created_at TIMESTAMPTZ DEFAULT NOW(),UNIQUE(source,external_id));
CREATE TABLE IF NOT EXISTS job_matches (id BIGSERIAL PRIMARY KEY,user_id UUID REFERENCES users(id) ON DELETE CASCADE,job_id BIGINT REFERENCES discovered_jobs(id) ON DELETE CASCADE,match_score INTEGER NOT NULL,status TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW(),UNIQUE(user_id,job_id));
CREATE TABLE IF NOT EXISTS career_runs (id BIGSERIAL PRIMARY KEY,user_id UUID REFERENCES users(id) ON DELETE CASCADE,status TEXT NOT NULL,jobs_discovered INTEGER DEFAULT 0,jobs_matched INTEGER DEFAULT 0,error_message TEXT,started_at TIMESTAMPTZ DEFAULT NOW(),finished_at TIMESTAMPTZ);
ALTER TABLE career_runs ADD COLUMN IF NOT EXISTS progress_stage TEXT;
ALTER TABLE career_runs ADD COLUMN IF NOT EXISTS progress_percent INTEGER NOT NULL DEFAULT 0;
CREATE TABLE IF NOT EXISTS source_workflows (id BIGSERIAL PRIMARY KEY,user_id UUID REFERENCES users(id) ON DELETE CASCADE,source TEXT NOT NULL,automation_mode TEXT NOT NULL,submission_mode TEXT NOT NULL,status TEXT NOT NULL,detail TEXT NOT NULL,last_checked_at TIMESTAMPTZ,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW(),UNIQUE(user_id,source));
CREATE TABLE IF NOT EXISTS platform_integrations (id BIGSERIAL PRIMARY KEY,user_id UUID REFERENCES users(id) ON DELETE CASCADE,source TEXT NOT NULL,permission_status TEXT NOT NULL DEFAULT 'not_requested',requested_at TIMESTAMPTZ,connected_at TIMESTAMPTZ,last_checked_at TIMESTAMPTZ,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW(),UNIQUE(user_id,source));
CREATE TABLE IF NOT EXISTS job_contact_checks (id BIGSERIAL PRIMARY KEY,user_id UUID REFERENCES users(id) ON DELETE CASCADE,job_id BIGINT REFERENCES discovered_jobs(id) ON DELETE CASCADE,contact_email TEXT,status TEXT NOT NULL,checked_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW(),UNIQUE(user_id,job_id));
CREATE TABLE IF NOT EXISTS admin_sessions (id BIGSERIAL PRIMARY KEY,token_hash TEXT UNIQUE NOT NULL,admin_email TEXT NOT NULL,expires_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ DEFAULT NOW(),last_seen_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS admin_audit_logs (id BIGSERIAL PRIMARY KEY,admin_email TEXT NOT NULL,action TEXT NOT NULL,target_type TEXT,target_id TEXT,metadata JSONB,created_at TIMESTAMPTZ DEFAULT NOW());
ALTER TABLE career_workflows ADD COLUMN IF NOT EXISTS timezone TEXT NOT NULL DEFAULT 'Asia/Kolkata';
ALTER TABLE career_workflows ADD COLUMN IF NOT EXISTS last_run_at TIMESTAMPTZ;
